export const KEY='viva-studio-v1';
export const fresh=()=>({version:1,questions:{},session:null,lastTopic:null});
export const status=(p,id)=>p.questions[id]?.attempts?.at(-1)?.status||'unseen';
export const weak=(p,id)=>['missed','partly'].includes(status(p,id));
export const past=(p,id)=>(p.questions[id]?.attempts||[]).some(a=>a.status!=='got');
export const shuffle=(a,rng=Math.random)=>{a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
export function balanced(items,n,rng=Math.random,counts={}){const pool=shuffle(items,rng),out=[];while(pool.length&&out.length<n){pool.sort((a,b)=>Math.min(...a.courseIds.map(c=>counts[c]||0))-Math.min(...b.courseIds.map(c=>counts[c]||0)));const q=pool.shift();out.push(q);for(const c of q.courseIds)counts[c]=(counts[c]||0)+1;}return out;}
export function filterQuestions(qs,f,p){return qs.filter(q=>(!f.courses?.length||q.courseIds.some(c=>f.courses.includes(c)))&&(!f.topic||q.topicIds.includes(f.topic))&&(!f.difficulty||q.difficulty===f.difficulty)&&(!f.type||q.type===f.type)&&(!f.essential||q.essential)&&(!f.connections||q.courseIds.length>1)&&(!f.status||({weak:weak(p,q.id),past:past(p,q.id),unseen:status(p,q.id)==='unseen',got:status(p,q.id)==='got',bookmarked:!!p.questions[q.id]?.bookmarked}[f.status])));}
export function queue(qs,f,p,rng=Math.random){const pool=filterQuestions(qs,f,p),n=Math.min(f.count||20,pool.length);if(f.mode==='all')return pool.map(q=>q.id);if(f.mode!=='mixed')return balanced(pool,n,rng).map(q=>q.id);const counts={},unseen=pool.filter(q=>status(p,q.id)==='unseen'),needs=pool.filter(q=>weak(p,q.id));let chosen=[...balanced(unseen,Math.ceil(n/2),rng,counts),...balanced(needs,Math.floor(n/2),rng,counts)];const used=new Set(chosen.map(q=>q.id));const extra=pool.filter(q=>!used.has(q.id)&&status(p,q.id)!=='got');chosen.push(...balanced(extra,n-chosen.length,rng,counts));const used2=new Set(chosen.map(q=>q.id));chosen.push(...balanced(pool.filter(q=>!used2.has(q.id)),n-chosen.length,rng,counts));return shuffle(chosen,rng).map(q=>q.id);}
export function mockQueue(qs,f,p,rng=Math.random){
 const allowed=filterQuestions(qs,f,p),allowedIds=new Set(allowed.map(q=>q.id)),used=new Set(),out=[],byId=new Map(qs.map(q=>[q.id,q]));
 const roots=balanced(f.difficulty?allowed:allowed.filter(q=>q.difficulty==='foundation'),8,rng);
 const specials=shuffle([...balanced(allowed.filter(q=>q.courseIds.length>1),2,rng),...balanced(allowed.filter(q=>q.difficulty==='challenge'),2,rng)],rng);
 const add=q=>{if(q&&!used.has(q.id)){out.push(q.id);used.add(q.id);}};
 for(let i=0;i<roots.length;i++){const q=roots[i];add(q);add(byId.get((q.followUps||[]).find(id=>allowedIds.has(id)&&!used.has(id))));if(i%2===1)add(specials.shift());}
 for(const q of specials)add(q);
 for(const q of balanced(allowed.filter(q=>!used.has(q.id)),30-out.length,rng))add(q);
 return out;
}

export function rate(p,id,result,attemptId,time=Date.now()){if(!['got','partly','missed'].includes(result))throw Error('Invalid rating');const r=p.questions[id]??={attempts:[],note:'',bookmarked:false};const a=r.attempts.find(x=>x.id===attemptId);if(a){a.status=result;a.at=time;}else r.attempts.push({id:attemptId,status:result,at:time});r.updatedAt=time;return p;}
export function parseProgress(raw,validIds){const x=JSON.parse(raw);if(!x||x.version!==1||!x.questions||typeof x.questions!=='object'||Array.isArray(x.questions))throw Error('This is not a Viva Studio progress file.');const p=fresh();for(const [id,r]of Object.entries(x.questions)){if(!validIds.has(id))continue;if(!r||!Array.isArray(r.attempts)||r.attempts.length>10000)throw Error('Invalid question history.');if(r.attempts.some(a=>!a||typeof a.id!=='string'||!['got','partly','missed'].includes(a.status)||!Number.isFinite(a.at)))throw Error('Invalid attempt.');p.questions[id]={attempts:r.attempts.map(a=>({id:a.id,status:a.status,at:a.at})),note:typeof r.note==='string'?r.note.slice(0,10000):'',bookmarked:r.bookmarked===true,updatedAt:Number(r.updatedAt)||0};}p.lastTopic=typeof x.lastTopic==='string'?x.lastTopic:null;const s=x.session;if(s&&Array.isArray(s.ids)&&s.ids.length>0&&new Set(s.ids).size===s.ids.length&&s.ids.every(id=>validIds.has(id))&&Number.isInteger(s.index)&&s.index>=0&&s.index<=s.ids.length&&['drill','mock'].includes(s.kind)&&typeof s.id==='string'&&['active','complete'].includes(s.state)){const answers={};for(const id of s.ids){const a=s.answers?.[id];if(a&&typeof a==='object'){answers[id]={visited:a.visited===true,shown:a.shown===true,skipped:a.skipped===true};if(['got','partly','missed'].includes(a.rating))answers[id].rating=a.rating;}}p.session={id:s.id,kind:s.kind,ids:s.ids,index:s.index,startedAt:Number(s.startedAt)||0,deadline:Number.isFinite(s.deadline)?s.deadline:null,state:s.state,answers};if(p.session.kind==='mock'&&p.session.deadline===null)p.session=null;}return p;}
export function readProgress(storage,ids){try{const raw=storage.getItem(KEY);return {data:raw?parseProgress(raw,ids):fresh(),available:true};}catch(e){return {data:fresh(),available:false,error:e.message};}}
export function saveProgress(storage,p){try{storage.setItem(KEY,JSON.stringify(p));return true;}catch{return false;}}
export function normalize(s){return s.toLowerCase().normalize('NFKD').replace(/behaviour/g,'behavior').replace(/organisation/g,'organization').replace(/[’']/g,'').replace(/[^\p{L}\p{N}\s]/gu,' ').replace(/\s+/g,' ').trim();}
